def sample(arrays,element,bary): # Evaluate the full native displacement/temperature interpolant and linearly reconstruct actual IP fields locally.
    tet=arrays['tet'][element];shape=np.column_stack([bary*(2.*bary-1.),4.*bary[:,0]*bary[:,1],4.*bary[:,1]*bary[:,2],4.*bary[:,2]*bary[:,0],4.*bary[:,0]*bary[:,3],4.*bary[:,1]*bary[:,3],4.*bary[:,2]*bary[:,3]]);nodal=np.einsum('pk,tpkd->tpd',shape,arrays['states'][:,tet,:4]);native_bary=np.full((4,4),.138196601125011);np.fill_diagonal(native_bary,.585410196624968);ip_weights=bary@np.linalg.inv(native_bary);ipids=len(arrays['fe_xyz'])+element[:,None]*4+np.arange(4);ip=np.einsum('pq,tpqd->tpd',ip_weights,arrays['states'][:,ipids,4:]);return np.concatenate([nodal,ip],axis=2) # Keep all local stress/plastic/flux components and disclose this comparison-only interpolation explicitly.
