    def von_mises(s): return np.sqrt(.5*((s[...,0]-s[...,1])**2+(s[...,1]-s[...,2])**2+(s[...,2]-s[...,0])**2)+3.*np.sum(s[...,3:]**2,axis=-1)) # Compare actual quadrature stress peaks without nodal extrapolation.
