    return {'coarse':str(coarse_folder),'fine':str(fine_folder),'kind':'full3D_actual_mesh_refinement','common_volume_fraction':coverage,'common_points':int(valid.sum()),'all_coarse_points':len(points),'sampling':'Every coarse native IP; true C3D10 nodal interpolation, linear reconstruction through four actual IP values for stress and history comparisons; no surrogate response reduction.','metrics':metrics,'limits':limits,'actual_native_peaks':{'coarse_peeq':pa,'fine_peeq':pb,'coarse_mises_MPa':va,'fine_mises_MPa':vb},'status':'DIAGNOSTIC_UNQUALIFIED' if allow_unqualified else ('PASS' if coverage>=.99 and all(metrics[k]<=v for k,v in limits.items()) else 'HOLD_MESH_REFINEMENT'),'native_seconds':ra['seconds']+rb['seconds']} # Refuse to call unobserved convergence or missing material volume acceptable.
